CREATE TABLE crm_linked_devices (owner_id TEXT PRIMARY KEY REFERENCES crm_users(id), token_hash TEXT NOT NULL UNIQUE, enabled INTEGER NOT NULL DEFAULT 1, desired TEXT NOT NULL DEFAULT 'idle', status TEXT NOT NULL DEFAULT 'offline', seen INTEGER NOT NULL DEFAULT 0, phone TEXT UNIQUE, qr TEXT NOT NULL DEFAULT '[]', qr_expires INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '', synced_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE crm_linked_commands (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES crm_users(id), lead_id TEXT NOT NULL REFERENCES crm_leads(id), peer TEXT NOT NULL, content TEXT NOT NULL, request_hash TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', result TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE INDEX crm_linked_commands_owner_state ON crm_linked_commands(owner_id,state,created);
CREATE UNIQUE INDEX crm_linked_commands_one_pending ON crm_linked_commands(owner_id,lead_id) WHERE state IN ('queued','running','uncertain');
